                            value: {
                                URL: getBaseUrl + getPath,
                                Method: 'GET',
                                Status: secondaryInfo.statusCode,
                                Body: secondaryInfo.body
                            }
                        });
                    }
                    if (isPostPostMode) {
                        addContext(this, {
                            title: 'Secondary Response Details',
                            value: {
                                URL: consolidatePostBaseUrl + '/api/ListWarningLabels',
                                Method: 'POST',
                                Status: secondaryInfo.statusCode,
                                Body: secondaryInfo.body
                            }
                        });
                    }
                    try {
